  const sx = x+wx+gx*0.3, sy = y+wy+gy*0.3;
  const src = [[160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0],[320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7],[240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3],[120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5],[360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6]];
  let aS=0, iS=0;
  for (const [sX,sY,f,sp] of src) { const d=Math.sqrt((sx-sX)**2+(sy-sY)**2); aS+=Math.sin(d*f-t*sp); iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5); }
